<?php declare(strict_types=1); $editing=$account!==null; ?>
<div class="mb-5"><a class="text-sm font-semibold text-navy-700" href="<?= e(admin_url('users')) ?>">← Back to users</a></div>
<form class="card max-w-2xl p-6" method="post" action="<?= e($editing?admin_url('users/'.$account['id']):admin_url('users')) ?>"><?= csrf_field() ?><div class="grid gap-5 sm:grid-cols-2"><div><label class="field-label">Name</label><input class="field" name="name" required maxlength="120" value="<?= e(old('name',$account['name']??'')) ?>"></div><div><label class="field-label">Email</label><input class="field" type="email" name="email" required maxlength="190" value="<?= e(old('email',$account['email']??'')) ?>"></div><div><label class="field-label">Role</label><select class="field" name="role"><?php foreach(ROLES as $key=>$r): ?><option value="<?= e($key) ?>" <?= old('role',$account['role']??'admin')===$key?'selected':'' ?>><?= e($r['label']) ?></option><?php endforeach; ?></select></div><?php if($editing): ?><div><label class="field-label">Status</label><select class="field" name="status"><option value="active" <?= $account['status']==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= $account['status']==='suspended'?'selected':'' ?>>Suspended</option></select></div><?php endif; ?><div class="sm:col-span-2"><label class="field-label"><?= $editing?'New password (leave blank to keep current)':'Temporary password' ?></label><input class="field" type="password" name="password" <?= $editing?'':'required' ?> minlength="12" autocomplete="new-password"><p class="mt-1 t-meta text-muted">At least 12 characters.</p></div></div><button class="btn btn-primary mt-7"><?= $editing?'Save account':'Create account' ?></button></form>
